import json,csv,hashlib
from pathlib import Path
R=Path.cwd();O=R/'outputs/expanded/mcgregor/four_bout';bouts=json.load(open(O/'bout_summary.json'));roster=[];foot=[]
for folder in ['pilot','expansion','expansion_extra']:
 B=R/'outputs/expanded/mcgregor'/folder
 for row in json.load(open(B/'manifest.json')):
  cid=row['anonymous_id'];p=B/'labels'/f'{cid}.json';meta=json.load(open(B/'audit'/f'{cid}.metadata.json'));prompt=B/'audit'/f'{cid}.prompt.txt';assert meta['prompt_sha256']==hashlib.sha256(prompt.read_text().encode()).hexdigest();assert not meta['tools_used'];assert all(hashlib.sha256((R/item['path']).read_bytes()).hexdigest()==item['sha256'] for item in meta['images']);d=json.load(open(p));roster.append({'folder':folder,'anonymous_id':cid,'source':row['source'],'source_start':row['start'],'label_path':str(p.relative_to(R)),'metadata_path':str((B/'audit'/f'{cid}.metadata.json').relative_to(R)),'target_identity_visibility':d['target_identity_visibility'],'physical_absence_is_not_inferred':True,'completed':True})
  if d['live_fight']=='yes' and d['likely_replay']=='no' and d['target_identity_visibility']=='high' and d['camera']['feet_observable_seconds_estimate']>0:
   for event in d['footwork']:
    if event['certainty'] in ['high','medium'] and any(s['phase']=='standing' and s['start']<=event['start'] and event['end']<=s['end'] for s in d['phases']):foot.append({'source':row['source'],'anonymous_id':cid,'source_time_start':row['start']+event['start'],'source_time_end':row['start']+event['end'],**event})
(O/'completed_roster.json').write_text(json.dumps(roster,indent=2));(O/'reported_footwork_events.json').write_text(json.dumps({'events':foot,'interpretation':'Visible labeled patterns and sequence lower bounds, not calibrated cadence. Step/shuffle/circle counts have different granularities and must not be summed into a single fluidity score. Empty or unobservable exposures remain missing.','unit':'event windows nested within four bouts'},indent=2))
measurements=[]
for folder in ['adaptive','adaptive_expansion']:
 d=json.load(open(R/'outputs/expanded/mcgregor'/folder/'validated_measurements.json'));measurements += [{**m,'evidence_folder':folder} for m in d['measurements']]
(O/'quiet_projection_measurements.json').write_text(json.dumps({'metric_selection':'Exploratory refinement after hip-joint candidates were not visually identifiable through shorts. Requires accepted visible landmarks rather than relaxing rejected hip ownership.','measurements':measurements,'units':'Projected image-plane ratios; per-bout nested anchors, not independent samples','limits':['Camera view and foreshortening differ; no averaged career trend.','Shoulder-to-ankle distance is a visible scale proxy, not anatomical height.','Sol acceptance is visual model review, not human or motion-capture ground truth.','Hip/torso lean and lead/rear weight distribution remain unverified.','Apparent heel states are model visual estimates; no force/contact measurement.']},indent=2))
flow=[]
for p in (R/'outputs/expanded/mcgregor/flow').glob('*.json'):
 d=json.load(open(p));pairs=d['pairs'];accepted=[p for p in pairs if p['accepted_background_model']];flow.append({'id':d['anonymous_id'],'source':d['source'],'standing_pairs':len(pairs),'background_fit_accepted_pairs':len(accepted),'background_fit_rejected_pairs':len(pairs)-len(accepted),'accepted_fraction':len(accepted)/len(pairs) if pairs else None})
(O/'camera_flow_diagnostic.json').write_text(json.dumps({'windows':flow,'interpretation':'Person-masked background LK + RANSAC similarity diagnostic only. Rejected fits/cuts cannot support camera-compensated footwork; accepted fits also retain parallax/missed-person/crowd confounds. No target motion or bounce derived from these fits.'},indent=2))
lines=['Four-bout McGregor movement evidence study — 28 windows, exploratory','', 'Result: native footage supports quantified observations within selected standing intervals. It does not establish a career shift from one named style to another. Four different opponents, rounds, weight/context and camera views remain confounded. The original two-bout systematic broadcast samples and later conditional standing supplements are kept separate in provenance.','', 'Completed coverage and reported visible attempt lower bounds:']
years={'obgm6JNtyVo':'2012 Cage Warriors','BCOy-PG8EIw':'2013 Holloway','khabib-mcgregor':'2018 Nurmagomedov','6yu2AWK4rxo':'2021 Poirier II'}
for b in bouts['bouts']:
 c=b['attempt_reported_lower_bounds'];lines.append(f"- {years[b['source']]}: {b['windows_labeled']} labeled windows; {b['identifiable_standing_seconds_estimate']:.2f}s identifiable standing; {b['feet_visible_seconds_estimate']:.2f}s feet-visible estimate; {c['punch']} reported punches and {c['kick']} reported kicks. Bounce-cycle lower bound {b['bounce_cycles_reported_lower_bound']} across {b['bounce_observable_windows']} windows with observable reported footwork.")
lines+=['','Counts are lower bounds from 4Hz observations, not full-bout strike totals or population rates. A zero reported lower bound does not establish absence. Empty arrays under poor visibility and unresolved identity are missing, not zero. Adjacent frames and anchors do not increase the four-bout analysis unit count.','', 'Quiet-anchor supplement: native full frames + separate RTMW candidates + fresh tool-free Sol landmark review. Anatomical hip centers were rejected as unobservable through shorts; hip-based or force/weight metrics are withheld. Visible ankle span divided by accepted same-side shoulder-to-ankle distance is retained as an image-plane scale proxy. Examples at source timestamps: 2012 252.50s =0.405; 2013 223.50s =0.433; 2018 657.50s =0.522; 2021 598.25s =0.322 (right-side scale). These are back, back, three-quarter and front views, so averaging them into a career direction would be invalid.','', 'Within-bout variation is substantial in the sampled quiet anchors: 2018 right-side ratios include0.332,0.481,0.522; 2021 includes0.322 and0.538. For independently accepted nose/ankle landmarks, 2013 widths normalized by nose-to-ankle-midpoint are0.271 and0.435 only0.75s apart, while one 2021 anchor is0.310. This variation and projection mismatch prevent a simple monotonic stance narrative. Wrist-to-head projection values are also retained where individually accepted, without assigning lead/rear roles.','', 'Heel observations include one apparently raised heel in both2013 and2021 anchors; a2018 anchor is visually labeled both flat. These are momentary model image estimates, not bodyweight distribution or physical contact measurements.','', 'Footwork events retain timestamps and evidence: steps, shuffles, approach, withdrawal and resets. Their count granularities differ, so no invented single fluidity score is reported. An independent8Hz sampling-density/action-response check is saved separately when complete; it has no prior labels or expected era/style direction.','', 'Camera checks: detected-person-masked background optical flow and robust similarity fits flag cuts and unstable camera estimates. These are diagnostics, not footwork. No screen-box displacement is called bounce; target footwork remains directly observed with explicit uncertainty.','', 'Design and limits: the2012 broadcast contains post-finish nonfight/replay segments. Initial rejected intervals were preserved, and four nonoverlapping live-standing windows were added by phase rather than movement outcome. Source-time sampling and phase-selected supplementation are different sampling designs. Exposure, view, range, pressure and round remain uneven. Broadcast names/faces/clothing are readable, so era blinding is incomplete despite anonymous prompts. The same model family provides all annotations and visual reviews; repeat agreement is not human gold truth. No new training, no career causal inference, no independent-frame p-values.','', 'Files: bout_summary.json, window_summary.csv, completed_roster.json, anchor_eligibility.json, quiet_projection_measurements.json, reported_footwork_events.json, camera_flow_diagnostic.json, native-comparison.jpg, validated-projection-comparison.jpg, clips/*.mp4. Each input image, prompt and tool-free model run has saved hashes and metadata.']
(O/'findings.txt').write_text('\n'.join(lines)+'\n');(O/'validation.json').write_text(json.dumps({'completed_windows':len(roster),'expected_windows':28,'tool_free_metadata_valid':True,'prompt_hashes_match':True,'image_hashes_match':True,'all_labels_per_bout_anchor_corrected':True,'no_career_trend_proof_claim':True,'no_training':True},indent=2));print('Published',len(roster),len(measurements),len(foot),len(flow))
